import argparse
import json
from pathlib import Path
from counterscene.part2 import frozen_env


def main():
    p=argparse.ArgumentParser();p.add_argument('--root',default='results/spatial_suite/ae_logical_v3/instances');p.add_argument('--out',required=True);a=p.parse_args()
