"""Verify complete feasible witnesses and structurally rederive B UNSAT proofs."""
import argparse,json,math
from pathlib import Path
from counterscene.part2 import frozen_env
from counterscene.spatial_suite import core


def prove(task,objects,soft):
    hard=[c for c in task['constraints'] if c.get('priority')=='hard']
    a,b=soft['args'][:2]
    def half(i):return min(objects[i]['size'][:2])/2
    if soft['type']=='distance':
        contact=next((h for h in hard if h['type']=='touching' and set(h['args'])=={a,b}),None)
        if contact:
            bound=math.sqrt(2)*((max(objects[a]['size'][:2])+max(objects[b]['size'][:2]))/2+core.TOL)
            if soft['range'][0]>bound:return dict(kind='contact_distance_bound',hard_ids=[contact['id']],upper_bound_m=bound,required_min_m=soft['range'][0])
    for direction in ('left_of','right_of','in_front_of','behind'):
        if soft['type']!=core.OPPOSITE[direction]:continue
        for h in hard:
            if h['type']==direction and h['args'][0]==a:
                middle=h['args'][1]
                other=next((x for x in hard if x['type']==direction and x['args']==[middle,b]),None)
                if other and 2*(half(a)+half(middle)+half(b))>3*core.TOL:
                    return dict(kind='transitive_direction',hard_ids=[h['id'],other['id']])
        for h in hard:
            if h['type']!='between' or h['args'][0]!=a or h['args'][2]!=b:continue
            start=h['args'][1]
            other=next((x for x in hard if x['type']==direction and x['args']==[start,b]),None)
            margin=half(a)+half(b)-core.TOL-core.BETWEEN_LATERAL
            if other and margin>0:
                return dict(kind='between_lateral_bound',hard_ids=[h['id'],other['id']],lateral_allowance_m=core.BETWEEN_LATERAL,contradiction_margin_m=margin)
    raise ValueError('No verified contradiction proof: '+soft['id'])


def main():
    p=argparse.ArgumentParser();p.add_argument('--root',default='results/spatial_suite/ae_logical_v3/instances');p.add_argument('--out',required=True);a=p.parse_args()
    rows=[]
    for folder in sorted(Path(a.root).glob('*-*')):
        env=frozen_env(folder);t=env.task;private=env.priv;gold=private['gold']
        proofs=[]
        if env.experiment!='D':
            objs,problems=core.build_objects(t,gold);assert not problems
            report=core.check_scene(t,gold);assert not report['physical']
            truth={r['id']:r['satisfied'] for r in report['constraints']}
            for c in t['constraints']:
                impossible=env.experiment=='B' and c['id'] in private['soft'] and not private['soft'][c['id']]['feasible']
                if impossible:
                    assert not truth[c['id']]
                    proofs.append(dict(id=c['id'],**prove(t,objs,c)))
                else:assert truth[c['id']],(folder.name,c['id'])
        action=dict(tool='submit',**gold) if env.experiment=='D' else dict(tool='submit',placements=gold)
        if env.experiment=='B':action['infeasible']=[k for k,v in private['soft'].items() if not v['feasible']]
        env.step(action);assert env.final()['success'],folder.name
        rows.append(dict(instance=folder.name,joint_feasible_witness=True,unsatisfiable_soft_proofs=proofs))
    out=Path(a.out);out.parent.mkdir(parents=True,exist_ok=True)
    out.write_text(json.dumps(dict(items=len(rows),rows=rows,all_passed=True,meaning='Hard and feasible-soft constraints jointly witnessed; impossible soft constraints certified separately'),indent=2),encoding='utf-8')
    print(json.dumps(dict(items=len(rows),unsat_proofs=sum(len(r['unsatisfiable_soft_proofs']) for r in rows),all_passed=True)))

if __name__=='__main__':main()
