"""Progressive installation episodes: execute, environment change, replan."""
import copy
from .survey_repair import make_survey_pair
from .observed_grounding import make_grounding_pair
from .calibrated_mechanism import make_calibration_pair


class ProgressiveEnv:
    def __init__(self,worlds,stages):
        self.worlds=worlds;self.stages=stages;self.stage=0
        self.current=copy.deepcopy(worlds[0]);self.turn=0;self.max_turns=stages*14
        self.done=False;self.log=[];self.accepted=[];self.last_result=None

    def __getattr__(self,key):return getattr(self.current,key)

    def prompt(self):
        text,images=self.current.prompt()
        return text+f'\nProgressive installation: {self.stages} ordered physical stages. Complete the current operation, then use commit_stage with the same program and answer fields as submit to execute and accept it. An external change follows accepted non-final stages; inspect/capture/calibrate the updated world and repair the previous solution. Final submit is for the last stage only. Accepted stages cannot be replaced by only a final scene. Total action cap: {self.max_turns}.',images

    def step(self,action):
        if self.done:return dict(error='Episode ended'),[]
        self.turn+=1
        obs={};images=[]
        tool=action.get('tool') if isinstance(action,dict) else None
        if tool=='submit' and self.stage<self.stages-1:
            obs=dict(error='Current installation must be executed with commit_stage before the external change occurs')
        elif tool=='commit_stage':
            trial=copy.deepcopy(self.current)
            trial.step(dict(action,tool='submit'))
            result=trial.final()
            if not result['success']:
                obs=dict(stage_accepted=False,result=result)
            else:
                self.accepted.append(dict(stage=self.stage,action=copy.deepcopy(action),result=result))
                self.stage+=1
                if self.stage==self.stages:
                    self.current=trial;self.done=True;self.last_result=result
                    obs=dict(stage_accepted=True,all_stages_completed=True)
                else:
                    self.current=copy.deepcopy(self.worlds[self.stage%len(self.worlds)])
                    obs=dict(stage_accepted=True,stage=self.stage,event='External update completed: remeasure the live installation/target/controller; preserve constraints and complete the next operation.')
        else:
            obs,images=self.current.step(action)
            if self.current.done:
                self.done=True;self.last_result=self.current.final()
        if self.turn>=self.max_turns:self.done=True
        obs['total_actions_left']=max(0,self.max_turns-self.turn)
        self.log.append(dict(turn=self.turn,stage=self.stage,action=copy.deepcopy(action),observation=copy.deepcopy(obs),n_images=len(images)))
        return obs,images

    def final(self):
        success=bool(self.last_result and self.last_result['success'] and (len(self.accepted)==self.stages or len(self.accepted)==self.stages-1 and self.current.submission is not None))
        return dict(success=success,stages_completed=len(self.accepted)+(1 if success and len(self.accepted)<self.stages else 0),stages_required=self.stages,last_stage_result=self.last_result)


def make_progressive(folder):
    exp=folder.name[0]
    factory=make_grounding_pair if exp=='C' else make_calibration_pair if exp=='D' else make_survey_pair
    worlds=factory(folder)
    level=folder.name.split('-')[1]
    stages={'L1':1,'L2':2,'L3':3,'k06':1,'k14':2,'k34':3}[level]
    return ProgressiveEnv(worlds,stages)
